const cam = mulus(p);
const latar = el('latarLangitMalam1');
if (latar) latar.setAttribute('transform', `scale(${(1.05 - cam * 0.05).toFixed(3)})`);

const gedung = el('gedungKementerian1');
if (gedung) gedung.setAttribute('transform', `scale(${(1.04 - cam * 0.04).toFixed(3)})`);

const jam = el('jamDindingGedung1');
if (jam) {
  const detak = (Math.sin(t * Math.PI * 2) > 0 ? 1 : 0) * 0.04;
  jam.setAttribute('transform', `scale(${(1 + detak).toFixed(3)})`);
}

const tRem = Math.min(1, t / 2.2);
const pMaju = mulus(tRem);
const sisaJarak = (1 - pMaju) * 850;

let hentak = 0;
if (t > 1.6 && t < 3.2) {
  const f = (t - 1.6) / 1.6;
  hentak = Math.sin(f * Math.PI * 2.5) * Math.exp(-f * 3) * -3.5;
}

const rombongan = el('rombonganMobilKPK1');
if (rombongan) {
  rombongan.setAttribute('transform', `translate(${sisaJarak.toFixed(1)}, ${hentak.toFixed(1)})`);
}

const rotRoda = (1 - pMaju) * -720;
const rodaD = el('rodaDepanVan1');
if (rodaD) rodaD.setAttribute('transform', `rotate(${rotRoda.toFixed(1)})`);
const rodaB = el('rodaBelakangVan1');
if (rodaB) rodaB.setAttribute('transform', `rotate(${rotRoda.toFixed(1)})`);

const pPintu = mulus(Math.max(0, Math.min(1, (t - 3.2) / 1.4)));
const pintu = el('pintuGeserVan1');
if (pintu) pintu.setAttribute('transform', `translate(${(-pPintu * 70).toFixed(1)}, 0)`);

const petugas = el('petugasSiluet1');
if (petugas) {
  const majuPetugas = mulus(Math.max(0, Math.min(1, (t - 3.6) / 1.6))) * 15;
  petugas.setAttribute('transform', `translate(${majuPetugas.toFixed(1)}, ${(napas * 1.2).toFixed(1)})`);
  petugas.setAttribute('opacity', Math.min(1, pPintu * 1.5).toFixed(2));
}

const debu = el('debuJalananMelayang1');
if (debu) {
  const tDebu = Math.max(0, t - 1.8);
  const pDebu = Math.min(1, tDebu / 4.5);
  const debuX = -pDebu * 80 + ombak * 10;
  const debuY = -pDebu * 35 + ombakC * 6;
  const alphaDebu = tDebu <= 0.6 ? tDebu / 0.6 : Math.max(0, 1 - (tDebu - 0.6) / 3.9);
  debu.setAttribute('transform', `translate(${debuX.toFixed(1)}, ${debuY.toFixed(1)}) scale(${(1 + pDebu * 0.8).toFixed(2)})`);
  debu.setAttribute('opacity', (alphaDebu * 0.75).toFixed(2));
}

const strobo = el('stroboDepan1');
if (strobo) {
  const kedipStrobo = Math.sin(t * 26) > 0.1 ? 0.95 : 0.15;
  strobo.setAttribute('opacity', kedipStrobo.toFixed(2));
}

const sorot = el('sorotLampuUtama1');
if (sorot) {
  const getarSorot = 0.88 + getar * 0.08 + Math.sin(t * 12) * 0.04;
  sorot.setAttribute('opacity', Math.max(0, Math.min(1, getarSorot)).toFixed(2));
}

const daunKiri = el('daunGerbangKiri1');
if (daunKiri) daunKiri.setAttribute('transform', `rotate(${(ombak * 0.4).toFixed(2)})`);
const daunKanan = el('daunGerbangKanan1');
if (daunKanan) daunKanan.setAttribute('transform', `rotate(${(-ombak * 0.4).toFixed(2)})`);

// 1. Pita segel KPK ditarik menyilang di kaca
const pTarik = mulus(Math.min(1, t / 1.6));
const pita = el('pitaSegelKPKMenyilang');
if (pita) {
  pita.style.clipPath = "inset(0 " + (100 - pTarik * 100).toFixed(1) + "% 0 0)";
  pita.setAttribute('opacity', t > 0.1 ? '1' : '0');
}

// 2. Petugas 1 (Penempel segel di pintu kaca) - Aksi menempel lalu menahan pose
const p1 = el('petugasTempelSegel1');
if (p1) {
  const majuP1 = mulus(Math.min(1, t / 1.4)) * 18;
  const napasP1 = napas * 1.5;
  p1.setAttribute('transform', "translate(" + majuP1.toFixed(1) + ", " + napasP1.toFixed(1) + ")");
}

// Efek pendar stiker saat ditekan
const efek = el('efekTekanSegel');
if (efek) {
  const aktifTekan = t >= 1.4 && t <= 2.2;
  efek.setAttribute('opacity', aktifTekan ? (0.7 + Math.sin(t * 15) * 0.3).toFixed(2) : '0');
}

// 3. Petugas 2 (Membawa koper dokumen keluar) - Gerak translasi UTUH
const p2 = el('petugasSeretKoper2');
if (p2) {
  const pJalan = mulus(Math.max(0, Math.min(1, (t - 1.0) / 4.8)));
  const sedangJalan = t > 1.0 && pJalan < 1;
  const langkah = sedangJalan ? fisika.langkah(t, 6.5, 4.0) : { ayun: 0, hentak: 0 };
  const xPos = -80 + pJalan * 380;
  const yPos = langkah.hentak + (sedangJalan ? 0 : napas * 1.2);
  p2.setAttribute('transform', "translate(" + xPos.toFixed(1) + ", " + yPos.toFixed(1) + ")");
}

// Ayunan lembut koper pada poros gagang (cx: 610, cy: 820) TANPA translate tambahan
const koper = el('bodiKoperHitam');
if (koper) {
  const sedangJalan = t > 1.0 && t < 5.8;
  const tiltKoper = sedangJalan ? -12 + Math.sin(t * 6.5) * 2.5 : -12;
  p2 && koper.setAttribute('transform', "rotate(" + tiltKoper.toFixed(1) + " 610 820)");
}

// 4. Atmosfer: Pantulan kaca berkedip lembut, satpam di foreground bernapas
const kaca = el('pantulanCahayaKaca');
if (kaca) {
  kaca.setAttribute('opacity', (0.35 + Math.sin(t * 1.8) * 0.12).toFixed(2));
}

const satpam = el('siluetSatpamTertegun');
if (satpam) {
  satpam.setAttribute('transform', "translate(0, " + (napas * 1.2).toFixed(1) + ")");
}

const debu = el('partikelDebuLobi');
if (debu) {
  debu.setAttribute('transform', "translate(" + (ombakC * 5).toFixed(1) + ", " + (-((t * 6) % 60)).toFixed(1) + ")");
}

// 1. Waktu Kejadian: Berkas jatuh di detik 0.7s, timbangan menghentak & membal
const tImpact = 0.75;
const tPost = Math.max(0, t - tImpact);
const isImpact = t >= tImpact;

// Spring physics: timbangan membal teredam setelah kejatuhan beban
// Di awal (t < 0.75s), timbangan hampir datar/seimbang (sudut = -18 deg dari posisi miring akhir)
// Setelah impact, sudut mengayun menuju 0 deg (posisi miring mantap SVG)
const ayun = isImpact ? (1 - fisika.pegas(tPost, 2.6, 0.62)) * -18 : -18;

// Titik poros pusat timbangan di (960, 275)
const cx = 960, cy = 275;
const lengan = el('lenganTimbanganMiring');
if (lengan) {
  lengan.setAttribute('transform', "rotate(" + ayun.toFixed(2) + " " + cx + " " + cy + ")");
}

// 2. Kinematika Titik Ujung Gantungan Piringan (Radius R = 368px)
// Saat batang berputar sebesar ayun (deg), ujung gantungan kiri (610, 160) dan kanan (1310, 390) bergeser:
const rad = (ayun * Math.PI) / 180;
const cosA = Math.cos(rad);
const sinA = Math.sin(rad);

// Pergeseran ujung gantungan kiri dari (610, 160)
const dxL = (610 - cx) * cosA - (160 - cy) * sinA + cx - 610;
const dyL = (610 - cx) * sinA + (160 - cy) * cosA + cy - 160;

// Pergeseran ujung gantungan kanan dari (1310, 390)
const dxR = (1310 - cx) * cosA - (390 - cy) * sinA + cx - 1310;
const dyR = (1310 - cx) * sinA + (390 - cy) * cosA + cy - 390;

// Piringan KIRI: Bergerak translasi murni mengikuti ujung kiri batang (tanpa double transform pada anak!)
const piringanKiri = el('piringanKiriTumpah');
if (piringanKiri) {
  piringanKiri.setAttribute('transform', "translate(" + dxL.toFixed(1) + ", " + dyL.toFixed(1) + ")");
}

// Piringan KANAN: Bergerak translasi murni mengikuti ujung kanan batang
const piringanKanan = el('piringanKananBebanUang');
if (piringanKanan) {
  piringanKanan.setAttribute('transform', "translate(" + dxR.toFixed(1) + ", " + dyR.toFixed(1) + ")");
}

// 3. Sertifikat yang tumpah melayang keluar dari piringan kiri saat tersentak
const kertasLepas = el('sertifikatMelayang2');
if (kertasLepas) {
  if (isImpact) {
    const pLepas = mulus(Math.min(1, tPost / 3.2));
    const melayangX = -pLepas * 95;
    const melayangY = pLepas * 160 + Math.sin(tPost * 3.5) * 6;
    const putar = pLepas * 35 + Math.sin(tPost * 4.0) * 8;
    kertasLepas.setAttribute('transform', "translate(" + melayangX.toFixed(1) + ", " + melayangY.toFixed(1) + ") rotate(" + putar.toFixed(1) + " 510 330)");
  } else {
    kertasLepas.setAttribute('transform', 'translate(0, 0)');
  }
}

// 4. Atmosfer: Debu emas melayang lembut, pendar sorot lampu
const debu = el('partikelDebuEmas');
if (debu) {
  debu.setAttribute('transform', "translate(" + (ombakC * 5).toFixed(1) + ", " + (ombak * 7).toFixed(1) + ")");
  debu.setAttribute('opacity', (0.4 + napas * 0.15).toFixed(2));
}

const sorot = el('sorotLampuDisplay');
if (sorot) {
  sorot.setAttribute('opacity', (0.8 + napas * 0.1).toFixed(2));
}

const camProg = mulus(Math.min(1, t / dur));
const camY = camProg * -18;
const camZoom = 1 + camProg * 0.05;

const elLatar = el('latarDindingMarmer');
if (elLatar) elLatar.setAttribute('transform', `translate(0, ${(camY * 0.25).toFixed(2)})`);

const elPejabat = el('pejabatBadan');
if (elPejabat) elPejabat.setAttribute('transform', `translate(0, ${(napas * 1.5).toFixed(2)})`);

const elMakelar = el('makelarBadan');
if (elMakelar) elMakelar.setAttribute('transform', `translate(0, ${(Math.sin(t * 1.8 + 1.2) * 1.5).toFixed(2)})`);

const elCahaya = el('cahayaLampuMeja');
if (elCahaya) elCahaya.setAttribute('opacity', (0.88 + Math.sin(t * 5) * 0.04).toFixed(3));

const elDebu = el('partikelDebuPengap');
if (elDebu) elDebu.setAttribute('transform', `translate(${(ombak * 3.5).toFixed(2)}, ${(-((t * 2.5) % 35)).toFixed(2)})`);

const elJarum = el('jarumDetik');
if (elJarum) {
  const subDetik = t % 1;
  const hentakan = subDetik < 0.12 ? mulus(subDetik / 0.12) : 1;
  const derajat = (Math.floor(t) + hentakan) * 6;
  elJarum.setAttribute('transform', `rotate(${derajat.toFixed(1)})`);
}

const pDorong = mulus(Math.max(0, Math.min(1, (t - 0.5) / 2.8)));
const pSambut = mulus(Math.max(0, Math.min(1, (t - 2.2) / 2.2)));
const pGenggam = mulus(Math.max(0, Math.min(1, (t - 4.2) / 1.4)));
const sentak = Math.sin(Math.max(0, Math.min(1, (t - 5.3) / 0.35)) * Math.PI) * 2.8;

const makelarDorongX = pDorong * 60;
const pejabatSambutX = -pSambut * 50;

const elMap = el('mapMerahMudaTransaksi');
if (elMap) elMap.setAttribute('transform', `translate(${makelarDorongX.toFixed(2)}, ${(Math.sin(pDorong * Math.PI) * -3).toFixed(2)})`);

const elLenganMakelar = el('lenganMakelarBawah');
if (elLenganMakelar) elLenganMakelar.setAttribute('transform', `translate(${(makelarDorongX + pGenggam * 4).toFixed(2)}, ${(sentak * 0.3).toFixed(2)})`);

const elTanganMakelar = el('tanganMakelarCengkeram');
if (elTanganMakelar) elTanganMakelar.setAttribute('transform', `translate(${(makelarDorongX + sentak).toFixed(2)}, 0) scale(${(1 + pGenggam * 0.04).toFixed(3)})`);

const elLenganPejabat = el('lenganPejabatBawah');
if (elLenganPejabat) elLenganPejabat.setAttribute('transform', `translate(${pejabatSambutX.toFixed(2)}, ${(-sentak * 0.3).toFixed(2)})`);

const elTanganPejabat = el('tanganPejabatMenyambut');
if (elTanganPejabat) elTanganPejabat.setAttribute('transform', `translate(${(pejabatSambutX - sentak * 0.8).toFixed(2)}, 0)`);

const elTransaksi = el('transaksiBawahMeja');
if (elTransaksi) elTransaksi.setAttribute('transform', `translate(0, ${camY.toFixed(2)}) scale(${camZoom.toFixed(3)})`);

const elFg = el('foregroundDokumenGelap');
if (elFg) elFg.setAttribute('transform', `translate(0, ${(camY * 1.5).toFixed(2)})`);

// skipped: transform-origin eksplisit jam dinding dan rotasi per-jari tangan, add when aset SVG memiliki titik pivot terpisah.

const sTameng = el('sertifikatTameng5');
const bayangan = el('bayanganTumpuan5');
const tancapan = el('tancapanBumi5');
const lembar = el('lembarDataHukum5');
const teks = el('teksSertifikat5');
const garuda = el('garudaEmas5');
const stempel = el('stempelResmi5');
const patok = el('patokBatas5');
const rKiri = el('bilahRumputKiri5');
const rKanan = el('bilahRumputKanan5');
const rDepan = el('rumputDepan5');
const pKiri = el('pelepahKelapaKiri5');
const pKanan = el('pelepahKelapaKanan5');
const pohon = el('pohonDesa5');
const awan = el('awanJauh5');
const glow = el('matahariGlow5');
const sorot = el('sorotCahaya5');
const serbuk = el('serbukSari5');

// GERAK CERITA: Sertifikat tameng meluncur jatuh, menancap kokoh, lalu membuka data hukum
const tJatuh = Math.min(1, t / 1.1);
const jatuhY = (1 - tJatuh * tJatuh) * -320;
const tImpact = Math.max(0, t - 1.1);
const getarTancap = tImpact < 0.6 ? Math.sin(tImpact * 28) * Math.exp(-tImpact * 7) * 14 : 0;
const bentang = mulus(Math.max(0, Math.min(1, (t - 1.2) / 1.6)));

if (sTameng) {
  sTameng.setAttribute('transform', `translate(0, ${(jatuhY + getarTancap).toFixed(2)})`);
}

if (bayangan) {
  const skalaB = (0.2 + tJatuh * 0.8).toFixed(2);
  bayangan.setAttribute('transform', `scale(${skalaB})`);
  bayangan.setAttribute('opacity', (tJatuh * 0.75).toFixed(2));
}

if (tancapan) {
  const retak = mulus(Math.max(0, Math.min(1, (t - 1.05) / 0.3)));
  tancapan.setAttribute('opacity', retak.toFixed(2));
  tancapan.setAttribute('transform', `scale(${(0.8 + retak * 0.2).toFixed(2)})`);
}

if (lembar) {
  lembar.setAttribute('transform', `scale(1, ${bentang.toFixed(3)})`);
  lembar.setAttribute('opacity', bentang.toFixed(2));
}

if (teks) {
  const teksMuncul = mulus(Math.max(0, Math.min(1, (t - 1.8) / 1.4)));
  teks.setAttribute('opacity', teksMuncul.toFixed(2));
  teks.setAttribute('transform', `translate(0, ${(8 * (1 - teksMuncul)).toFixed(1)})`);
}

// GERAK PENEGAS: Stempel kepastian hukum & kilau janji indah
const tStempel = Math.max(0, t - 3.2);
const capStempel = tStempel < 0.5 ? Math.sin(tStempel * 12) * Math.exp(-tStempel * 6) : 0;
const capSkala = mulus(Math.min(1, tStempel / 0.3));

if (stempel) {
  stempel.setAttribute('transform', `scale(${(capSkala + capStempel * 0.25).toFixed(2)})`);
  stempel.setAttribute('opacity', capSkala.toFixed(2));
}

const kilauEmas = mulus(Math.max(0, Math.min(1, (t - 5.2) / 1.5)));
const pendarIndah = kilauEmas * (0.85 + 0.15 * Math.sin(t * 4));

if (garuda) {
  garuda.setAttribute('transform', `scale(${(1 + pendarIndah * 0.08).toFixed(3)})`);
}

if (sorot) {
  sorot.setAttribute('opacity', (0.25 + napas * 0.1 + pendarIndah * 0.35).toFixed(2));
}

if (glow) {
  glow.setAttribute('transform', `scale(${(1 + napas * 0.04 + pendarIndah * 0.08).toFixed(3)})`);
}

if (patok) {
  const hentakPatok = tImpact < 0.5 ? Math.sin(tImpact * 24) * Math.exp(-tImpact * 8) * 3 : 0;
  patok.setAttribute('transform', `translate(0, ${hentakPatok.toFixed(2)})`);
}

// GERAK HIDUP: Angin pedesaan, dedaunan, rumput, awan, serbuk melayang
const angin = ombak;
const anginLaju = Math.sin(t * 3.1);

if (rKiri) rKiri.setAttribute('transform', `rotate(${(angin * 7 + (tImpact < 0.4 ? 6 : 0)).toFixed(2)})`);
if (rKanan) rKanan.setAttribute('transform', `rotate(${(Math.sin(t * 2.5 + 0.8) * 8).toFixed(2)})`);
if (rDepan) rDepan.setAttribute('transform', `rotate(${(anginLaju * 5).toFixed(2)})`);
if (pKiri) pKiri.setAttribute('transform', `rotate(${(Math.sin(t * 1.5) * 3).toFixed(2)})`);
if (pKanan) pKanan.setAttribute('transform', `rotate(${(Math.sin(t * 1.4 + 1.2) * 3.5).toFixed(2)})`);
if (pohon) pohon.setAttribute('transform', `rotate(${(Math.sin(t * 1.2 + 0.5) * 1.2).toFixed(2)})`);

if (awan) {
  awan.setAttribute('transform', `translate(${(t * 3.5).toFixed(1)}, 0)`);
}

if (serbuk) {
  serbuk.setAttribute('transform', `translate(${(ombakC * 10).toFixed(1)}, ${(-t * 8).toFixed(1)})`);
  serbuk.setAttribute('opacity', (0.4 + napas * 0.2).toFixed(2));
}

const pejabat = el('pejabatATR6');
if (pejabat) {
  const maju = mulus(Math.min(1, Math.max(0, (t - 0.5) / 2.0)));
  pejabat.setAttribute('transform', `translate(${(maju * 24).toFixed(1)}, ${(napas * 1.5).toFixed(2)})`);
}

const warga = el('wargaDesa6');
if (warga) {
  const maju = mulus(Math.min(1, t / 1.5));
  const bungkuk = mulus(Math.min(1, Math.max(0, (t - 1.0) / 1.8)));
  const tegak = mulus(Math.min(1, Math.max(0, (t - 3.6) / 1.8)));
  const dx = -35 + maju * 35 - bungkuk * 8 + tegak * 4;
  const dy = bungkuk * 20 - tegak * 10 + napas * 1.4;
  warga.setAttribute('transform', `translate(${dx.toFixed(1)}, ${dy.toFixed(1)})`);
}

const map = el('mapSertifikatBiru6');
if (map) {
  const serah = mulus(Math.min(1, Math.max(0, (t - 1.0) / 2.2)));
  // ponytail: translasi linear map cukup mewakili serah-terima; upgrade ke fisika.ikat jika ada titik jangkar tangan
  map.setAttribute('transform', `translate(${(serah * 52).toFixed(1)}, ${(serah * -6 + napas * 1.0).toFixed(2)})`);
}

const tanganPamer = el('tanganWargaPamer6');
if (tanganPamer) {
  const tampil = mulus(Math.min(1, Math.max(0, (t - 3.4) / 0.5)));
  tanganPamer.setAttribute('opacity', tampil.toFixed(2));
}

const blitz = el('kilatBlitzKamera6');
if (blitz) {
  const flashTimes = [2.2, 2.5, 3.2, 3.5, 3.8, 4.4, 4.8, 5.3, 5.9, 6.3, 6.7, 7.2];
  let intensitas = 0;
  for (let i = 0; i < flashTimes.length; i++) {
    const dt = t - flashTimes[i];
    if (dt >= 0 && dt < 0.2) intensitas = Math.max(intensitas, 1 - dt / 0.2);
  }
  blitz.setAttribute('opacity', (intensitas * 0.95).toFixed(2));
}

const tanamanKiri = el('tanamanPanggungKiri6');
if (tanamanKiri) tanamanKiri.setAttribute('transform', `translate(0, ${(ombak * 1.5).toFixed(2)})`);

const tanamanKanan = el('tanamanPanggungKanan6');
if (tanamanKanan) tanamanKanan.setAttribute('transform', `translate(0, ${(ombakC * 1.5).toFixed(2)})`);

const confetti = el('confettiJatuh6');
if (confetti) {
  const jatuh = mulus(Math.min(1, Math.max(0, (t - 1.8) / 5.5))) * 140;
  confetti.setAttribute('transform', `translate(${(Math.sin(t * 2.4) * 10).toFixed(1)}, ${jatuh.toFixed(1)})`);
  confetti.setAttribute('opacity', mulus(Math.min(1, Math.max(0, (t - 1.8) / 0.8))).toFixed(2));
}

const fotografer = el('fotograferKanan6');
if (fotografer) {
  const sentak = t > 2.5 ? Math.sin(t * 14) * 1.2 : 0;
  fotografer.setAttribute('transform', `translate(${sentak.toFixed(2)}, ${(napas * 1.2).toFixed(2)})`);
}

const kameraTV = el('kameraTVKiri6');
if (kameraTV) kameraTV.setAttribute('transform', `translate(0, ${(napas * 0.9).toFixed(2)})`);

const pers = el('lapisDepanWartawan6');
if (pers) pers.setAttribute('transform', `translate(${(ombak * 1.0).toFixed(2)}, ${(napas * 0.8).toFixed(2)})`);

const mikrofon = el('kumpulanMikrofonPers6');
if (mikrofon) mikrofon.setAttribute('transform', `translate(0, ${(Math.sin(t * 1.5) * 0.7).toFixed(2)})`);

skipped: skeletal IK rigging dan partikel confetti individu, add when aset dipisah per-tulang/partikel.

const pKamera = mulus(Math.min(1, t / dur));
const pGores = mulus(Math.max(0, Math.min(1, (t - 1.0) / 5.2)));

const pena = el('penaMerah7');
if (pena) {
  const x = pGores * 150;
  const y = Math.sin(pGores * Math.PI) * -15 + pGores * 40;
  const gesek = (pGores > 0 && pGores < 1) ? Math.sin(t * 28) * 0.4 : 0;
  pena.setAttribute('transform', `translate(${x.toFixed(1)}, ${(y + gesek).toFixed(1)}) rotate(${(-20 + pGores * 6).toFixed(1)})`);
}

const garis = el('garisMerahBaru7');
