    const skala = (0.2 + pSentuh * 2.2).toFixed(2);
    const opasitas = Math.max(0, 1 - pSentuh).toFixed(2);
    efekSentuh.setAttribute('transform', `scale(${skala})`);
    efekSentuh.setAttribute('opacity', opasitas);
  } else {
