const tanganRangkul = el('tanganRangkulAnak');
if (tanganRangkul) {
  tanganRangkul.setAttribute('transform', `translate(${(pRangkul * 5).toFixed(1)}, ${(pRangkul * 3).toFixed(1)})`);
}

const lenganTunjuk = el('porosLenganAyah') || el('ayahLenganKananMenunjuk');
if (lenganTunjuk) {
  const sudutTunjuk = -pTunjuk * 36 + sentakTunjuk;
  lenganTunjuk.setAttribute('transform', `rotate(${sudutTunjuk.toFixed(2)})`);
}

const jari = el('jariMenunjuk');
if (jari) {
  const mekarJari = mulus(Math.min(1, Math.max(0, (t - 3.8) / 0.8)));
  jari.setAttribute('transform', `scale(${(1 + mekarJari * 0.08).toFixed(3)})`);
}

const kepalaAyah = el('ayahKepala');
if (kepalaAyah) {
  const nolehPandang = mulus(Math.min(1, Math.max(0, (t - 2.8) / 1.6)));
  const rotAyah = (pRangkul * 4) - (nolehPandang * 6);
  kepalaAyah.setAttribute('transform', `rotate(${rotAyah.toFixed(2)})`);
}

const kepalaAnak = el('anakKepala');
if (kepalaAnak) {
  const rotAnak = -pTatapAnak * 8 + (pRangkul * 2.5);
  kepalaAnak.setAttribute('transform', `rotate(${rotAnak.toFixed(2)})`);
}

const badanAyah = el('ayahBadan');
if (badanAyah) {
  badanAyah.setAttribute('transform', `translate(0, ${(napas * 1.2).toFixed(2)})`);
}

const badanAnak = el('anakBadan');
if (badanAnak) {
  const napasAnak = Math.sin(t * 1.8 - 0.4);
  badanAnak.setAttribute('transform', `translate(0, ${(napasAnak * 0.9).toFixed(2)})`);
}

const bayangan = el('bayanganSubjek');
if (bayangan) {
