}

const ayun1 = Math.sin(t * 2.2) * 5.0;
const ayun2 = Math.sin(t * 2.2 + 0.9) * 4.2;
const ayun3 = Math.sin(t * 2.2 + 1.7) * 4.8;
const ayun4 = Math.sin(t * 2.2 + 2.5) * 3.8;

const bKiri1 = el('batangAyunKiri1');
if (bKiri1) bKiri1.setAttribute('transform', `rotate(${ayun1.toFixed(2)})`);
const tKiri1 = el('bulirPadiTangkai1');
if (tKiri1) tKiri1.setAttribute('transform', `rotate(${(ayun1 * 1.25).toFixed(2)})`);

const bKiri2 = el('batangAyunKiri2');
if (bKiri2) bKiri2.setAttribute('transform', `rotate(${ayun2.toFixed(2)})`);
const tKiri2 = el('bulirPadiTangkai2');
if (tKiri2) tKiri2.setAttribute('transform', `rotate(${(ayun2 * 1.2).toFixed(2)})`);

const bKanan1 = el('batangAyunKanan1');
if (bKanan1) bKanan1.setAttribute('transform', `rotate(${ayun3.toFixed(2)})`);
const tKanan1 = el('bulirPadiKanan1');
if (tKanan1) tKanan1.setAttribute('transform', `rotate(${(ayun3 * 1.25).toFixed(2)})`);

const bKanan2 = el('batangAyunKanan2');
if (bKanan2) bKanan2.setAttribute('transform', `rotate(${ayun4.toFixed(2)})`);
const tKanan2 = el('bulirPadiKanan2');
if (tKanan2) tKanan2.setAttribute('transform', `rotate(${(ayun4 * 1.2).toFixed(2)})`);

const lapisKiri = el('lapisDepanPadiKiri');
if (lapisKiri) lapisKiri.setAttribute('transform', `rotate(${(ayun1 * 0.35).toFixed(2)})`);

const lapisKanan = el('lapisDepanPadiKanan');
if (lapisKanan) lapisKanan.setAttribute('transform', `rotate(${(ayun3 * 0.35).toFixed(2)})`);

const burung = el('kawananBurung');
if (burung) {
  const bx = (t / dur) * 140;
  const by = -Math.sin(t * 1.4) * 5;
  burung.setAttribute('transform', `translate(${bx.toFixed(1)}, ${by.toFixed(1)})`);
}

const matahari = el('matahariSore');
if (matahari) {
  matahari.setAttribute('transform', `translate(0, ${(p * 8).toFixed(1)}) scale(${(1 + napas * 0.012).toFixed(3)})`);
}

const jerami = el('partikelJeramiEmas');
if (jerami) {
  const jx = Math.sin(t * 1.3) * 10 + (p * 18);
  const jy = Math.cos(t * 1.1) * 6 - (p * 12);
  jerami.setAttribute('transform', `translate(${jx.toFixed(1)}, ${jy.toFixed(1)})`);
  jerami.setAttribute('opacity', (0.5 + napas * 0.25).toFixed(2));
}

const gunung = el('pegununganJauh');
if (gunung) {
  gunung.setAttribute('transform', `translate(0, ${(p * 3.5).toFixed(1)})`);
}

