const langit = el('latarLangitFajar50');
if (langit) langit.setAttribute('opacity', (0.75 + 0.25 * mulus(Math.min(1, t / 4.0))).toFixed(2));

const sinar = el('sorotSinarFajar50');
if (sinar) sinar.setAttribute('opacity', (0.35 + 0.15 * napas).toFixed(2));

const gedung = el('gedungKeadilanSiluet50');
if (gedung) gedung.setAttribute('transform', `translate(0, ${(camPush * -4).toFixed(1)})`);

const pilar = el('deretanPilar50');
if (pilar) pilar.setAttribute('transform', `translate(0, ${(camPush * -7).toFixed(1)})`);

const pPatok = Math.min(1, Math.max(0, (t - 3.2) / 1.4));
const tancap = pPatok * pPatok;
const tancapSelesai = pPatok >= 1;

const tanah = el('tanahBumiPertiwi50');
if (tanah) {
  const getarTancap = (t >= 4.6 && t <= 5.1) ? Math.sin((t - 4.6) * 45) * (1 - (t - 4.6) / 0.5) * 2.5 : 0;
  tanah.setAttribute('transform', `translate(0, ${(getarTancap + camPush * -10).toFixed(1)})`);
}

const patok = el('patokBatasTanah50');
if (patok) {
  const yPatok = (1 - tancap) * -160;
  patok.setAttribute('transform', `translate(0, ${yPatok.toFixed(1)})`);
  patok.setAttribute('opacity', pPatok > 0 ? '1' : '0');
}

const pPerisai = mulus(Math.min(1, Math.max(0, (t - 1.6) / 2.0)));
const yPerisai = (1 - pPerisai) * 55;
const denyutPelindung = pPerisai >= 1 ? 1 + 0.03 * denyut : 1;

const perisai = el('perisaiHukum50');
if (perisai) {
  perisai.setAttribute('transform', `translate(0, ${(yPerisai + camPush * -10).toFixed(1)}) scale(${denyutPelindung.toFixed(3)})`);
  perisai.setAttribute('opacity', Math.min(1, 0.2 + pPerisai * 0.8).toFixed(2));
}

const timbangan = el('timbanganKeadilan50');
if (timbangan) {
  const ayunRedam = (t > 3.6 && t < 6.0) ? Math.sin((t - 3.6) * 4.5) * Math.max(0, 1 - (t - 3.6) / 2.4) * 2.5 : 0;
  timbangan.setAttribute('transform', `translate(0, ${(yPerisai + camPush * -10).toFixed(1)}) rotate(${ayunRedam.toFixed(2)})`);
  timbangan.setAttribute('opacity', Math.min(1, 0.2 + pPerisai * 0.8).toFixed(2));
}

const partikel = el('partikelCahayaEmbun50');
if (partikel) {
  const driftY = -((t * 14) % 60);
  partikel.setAttribute('transform', `translate(0, ${driftY.toFixed(1)})`);
  partikel.setAttribute('opacity', (0.35 + 0.25 * napas).toFixed(2));
}

const rKiri = el('rumputKiri50');
if (rKiri) rKiri.setAttribute('transform', `rotate(${(ombak * 2.8).toFixed(2)})`);

const rKanan = el('rumputKanan50');
