const rumputDepan = el('lapisDepanRumputEmbun50');
if (rumputDepan) {
  const goyangDepan = ombak * 1.8;
  rumputDepan.setAttribute('transform', `translate(${goyangDepan.toFixed(1)}, ${(camPush * -14).toFixed(1)})`);
}

